import { useForm } from "react-hook-form"
import Input from "../../Input/Input";
import Tarjeta from "../../ComponentesFormulario/Tarjeta/Tarjeta";
import Boton from '../../Boton/Boton'
import '../NuevaMarca/NuevaMarca.css'
import { useState } from 'react'
import { toast } from "sonner";
import { useValidarSesion } from "../../../hooks/useValidarSesion";

export default function ModificarCategoria({ onGuardar, id_categoria }) {

    const {token } = useValidarSesion(); // valida la sesion y obtiene datos del usuario desde zustands

    /////// HOOK FORM
    const { register, handleSubmit, formState: { errors } } = useForm({

    });

    /////// CREACION PUT DE CATEGORIA
    const onSubmit = async (data) => {
        setCargando(true);
    const route = `${import.meta.env.VITE_API_BASE_URL}/api/categoria/${id_categoria}`
        try {
            const respuesta = await fetch(route, {
                method: 'PUT',
                headers: {
                    'Content-Type': 'application/json',
                    'Accept': 'application/json',
                    'Authorization': `Bearer ${token}`
                },
                body: JSON.stringify(data),
            });

             // Intentamos leer siempre la respuesta (aunque haya error)
            const dataRespuestaCategoria = await respuesta.json().catch(() => ({}));

            if (!respuesta.ok) {
                const mensajeError = dataRespuestaCategoria?.error || "Error al modificar la categoria.";
                toast.error(mensajeError, { className: "__toaster_error" });
                return;


            }
        
            toast.success("Categoria modificada correctamente.",{className:"success"});
            onGuardar();

        } catch (error) {
            console.error('Error en la solicitud:', error);
            toast.error("Error inesperado al modificar la categoria.",{className:"__toaster_error"});
        } finally {
            setCargando(false);
        }
    };


    /////////// ESTADO PARA SABER CUANDO SE ESTA CARGANDO (SE ESTAN TRAYENDO LOS DATOS)
    const [cargando, setCargando] = useState(false);

    ////// LAYOUT
    return (
        <>
            {cargando && <div className='__cargando_fondo'><div className="__cargando"></div> </div>}
            <form onSubmit={handleSubmit(onSubmit)} className="__form_nueva_marca_categoria">
                <Tarjeta descripcion="Modificar Categoria" forid="categoria" mensajeError={errors.nombre_categoria?.message} >
                    <Input
                        tipo="text"
                        id="categoria"
                        {...register("nombre_categoria", { required: { value: true, message: "Ingrese nueva Categoria" } })}
                    />
                </Tarjeta>
                <Boton descripcion='Modificar' habilitado submit></Boton>
            </form>
        </>

    )

}